COMMENT ON TABLE resumes IS 'Resume file metadata. At most one current resume per student.';
COMMENT ON COLUMN resumes.storage_key IS 'Private object-storage key. Serve through short-lived signed access only.';
COMMENT ON COLUMN resumes.share_with_recruiters IS 'Recruiters see it only for roles the student applies to.';
COMMENT ON COLUMN resumes.deleted_at IS 'Set when the student deletes the resume. The file is removed from storage.';

