	CONSTRAINT ck_opportunities_pay_order CHECK (pay_max IS NULL OR pay_min IS NULL OR pay_max >= pay_min), 
	CONSTRAINT ck_opportunities_cgpa_range CHECK (min_cgpa IS NULL OR min_cgpa BETWEEN 0 AND 10), 
	CONSTRAINT ck_opportunities_openings_positive CHECK (openings >= 1), 
	CONSTRAINT fk_opportunities_company_id_companies FOREIGN KEY(company_id) REFERENCES companies (id) ON DELETE CASCADE, 
	CONSTRAINT fk_opportunities_posted_by_users FOREIGN KEY(posted_by) REFERENCES users (id) ON DELETE RESTRICT, 
	CONSTRAINT ck_opportunities_jobtype CHECK (job_type IN ('internship', 'full_time')), 
	CONSTRAINT ck_opportunities_workmode CHECK (work_mode IN ('on_site', 'hybrid', 'remote')), 
	CONSTRAINT ck_opportunities_payperiod CHECK (pay_period IN ('monthly', 'yearly', 'one_time')), 
	CONSTRAINT ck_opportunities_listingstatus CHECK (status IN ('draft', 'pending_review', 'published', 'paused', 'closed', 'rejected')), 
	CONSTRAINT fk_opportunities_duplicated_from_id_opportunities FOREIGN KEY(duplicated_from_id) REFERENCES opportunities (id) ON DELETE SET NULL
);
CREATE INDEX ix_opportunities_browse ON opportunities (status, application_deadline);
CREATE INDEX ix_opportunities_company ON opportunities (company_id, status);
CREATE INDEX ix_opportunities_title ON opportunities (title);
COMMENT ON TABLE opportunities IS 'Internship and job listings. updated_at shows students when a listing last changed.';
COMMENT ON COLUMN opportunities.external_apply_url IS 'Set when applications are completed on the company''s own site.';

CREATE TABLE practice_answers (
	id UUID NOT NULL, 
	student_id UUID NOT NULL, 
	question_id UUID NOT NULL, 
	answer_text TEXT NOT NULL, 
	feedback JSONB, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	CONSTRAINT pk_practice_answers PRIMARY KEY (id), 
	CONSTRAINT fk_practice_answers_student_id_users FOREIGN KEY(student_id) REFERENCES users (id) ON DELETE CASCADE, 
	CONSTRAINT fk_practice_answers_question_id_interview_questions FOREIGN KEY(question_id) REFERENCES interview_questions (id) ON DELETE CASCADE
);
CREATE INDEX ix_practice_answers_student ON practice_answers (student_id, created_at);
COMMENT ON TABLE practice_answers IS 'Typed practice answers. Audio is not stored.';
COMMENT ON COLUMN practice_answers.feedback IS 'Relevance, clarity and completeness notes.';

CREATE TABLE project_skills (
	project_id UUID NOT NULL, 
	skill_id UUID NOT NULL, 
	CONSTRAINT pk_project_skills PRIMARY KEY (project_id, skill_id), 
	CONSTRAINT fk_project_skills_project_id_student_projects FOREIGN KEY(project_id) REFERENCES student_projects (id) ON DELETE CASCADE, 
	CONSTRAINT fk_project_skills_skill_id_skills FOREIGN KEY(skill_id) REFERENCES skills (id) ON DELETE CASCADE
);
COMMENT ON TABLE project_skills IS 'Skills demonstrated by a project.';

CREATE TABLE recruiter_profiles (
	user_id UUID NOT NULL, 
	company_id UUID NOT NULL, 
	full_name VARCHAR(160) NOT NULL, 
	job_title VARCHAR(120), 
	phone VARCHAR(32), 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	CONSTRAINT pk_recruiter_profiles PRIMARY KEY (user_id), 
	CONSTRAINT fk_recruiter_profiles_user_id_users FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, 
	CONSTRAINT fk_recruiter_profiles_company_id_companies FOREIGN KEY(company_id) REFERENCES companies (id) ON DELETE CASCADE
);
CREATE INDEX ix_recruiter_profiles_company ON recruiter_profiles (company_id);
COMMENT ON TABLE recruiter_profiles IS 'Recruiter account details and their company.';

CREATE TABLE resume_analyses (
	id UUID NOT NULL, 
	resume_id UUID NOT NULL, 
	job_role_id UUID, 
	guidance_score INTEGER NOT NULL, 
	checklist JSONB NOT NULL, 
	suggestions JSONB NOT NULL, 
	analyser_version VARCHAR(32) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	CONSTRAINT pk_resume_analyses PRIMARY KEY (id), 
	CONSTRAINT ck_resume_analyses_score_range CHECK (guidance_score BETWEEN 0 AND 100), 
	CONSTRAINT fk_resume_analyses_resume_id_resumes FOREIGN KEY(resume_id) REFERENCES resumes (id) ON DELETE CASCADE, 
	CONSTRAINT fk_resume_analyses_job_role_id_job_roles FOREIGN KEY(job_role_id) REFERENCES job_roles (id) ON DELETE SET NULL
);
CREATE INDEX ix_resume_analyses_resume ON resume_analyses (resume_id);
COMMENT ON TABLE resume_analyses IS 'Resume feedback. Suggestions are reviewed by the student before anything changes.';
COMMENT ON COLUMN resume_analyses.guidance_score IS 'Guidance only. Not an ATS score and not a selection guarantee.';

CREATE TABLE resume_extracts (
	resume_id UUID NOT NULL, 
	parse_status VARCHAR(24) NOT NULL, 
	text TEXT, 
	parser_version VARCHAR(32) NOT NULL, 
	parsed_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	CONSTRAINT pk_resume_extracts PRIMARY KEY (resume_id), 
	CONSTRAINT ck_resume_extracts_status_values CHECK (parse_status IN ('ok','failed','needs_ocr')), 
	CONSTRAINT fk_resume_extracts_resume_id_resumes FOREIGN KEY(resume_id) REFERENCES resumes (id) ON DELETE CASCADE
);
COMMENT ON TABLE resume_extracts IS 'Text read from a resume, kept apart from the main resume record.';
COMMENT ON COLUMN resume_extracts.text IS 'Sensitive. Deleted with the resume and never logged.';

CREATE TABLE student_profiles (
	user_id UUID NOT NULL, 
	full_name VARCHAR(160) NOT NULL, 
	phone VARCHAR(32), 
	photo_key VARCHAR(255), 
	college_id UUID NOT NULL, 
	department_id UUID, 
	batch_id UUID, 
	course VARCHAR(120), 
	year_of_study INTEGER, 
	cgpa NUMERIC(4, 2), 
	percentage NUMERIC(5, 2), 
	completion_pct INTEGER DEFAULT 0 NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	CONSTRAINT pk_student_profiles PRIMARY KEY (user_id), 
	CONSTRAINT ck_student_profiles_year_range CHECK (year_of_study BETWEEN 1 AND 6), 
	CONSTRAINT ck_student_profiles_cgpa_range CHECK (cgpa BETWEEN 0 AND 10), 
	CONSTRAINT ck_student_profiles_percentage_range CHECK (percentage BETWEEN 0 AND 100), 
	CONSTRAINT ck_student_profiles_completion_range CHECK (completion_pct BETWEEN 0 AND 100), 
	CONSTRAINT fk_student_profiles_user_id_users FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, 
	CONSTRAINT fk_student_profiles_college_id_colleges FOREIGN KEY(college_id) REFERENCES colleges (id) ON DELETE RESTRICT, 
	CONSTRAINT fk_student_profiles_department_id_departments FOREIGN KEY(department_id) REFERENCES departments (id) ON DELETE SET NULL, 
	CONSTRAINT fk_student_profiles_batch_id_batches FOREIGN KEY(batch_id) REFERENCES batches (id) ON DELETE SET NULL
);
CREATE INDEX ix_student_profiles_college ON student_profiles (college_id, department_id, batch_id);
COMMENT ON TABLE student_profiles IS 'Student profile. Drives recommendations, readiness and college reports.';
COMMENT ON COLUMN student_profiles.photo_key IS 'Private object-storage key. Never a public URL.';

CREATE TABLE applications (
	id UUID NOT NULL, 
	opportunity_id UUID NOT NULL, 
	student_id UUID NOT NULL, 
	resume_id UUID, 
	cover_note TEXT, 
	status VARCHAR(24) DEFAULT 'applied' NOT NULL, 
	applied_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	CONSTRAINT pk_applications PRIMARY KEY (id), 
	CONSTRAINT uq_applications_opportunity_student UNIQUE (opportunity_id, student_id), 
	CONSTRAINT fk_applications_opportunity_id_opportunities FOREIGN KEY(opportunity_id) REFERENCES opportunities (id) ON DELETE CASCADE, 
	CONSTRAINT fk_applications_student_id_users FOREIGN KEY(student_id) REFERENCES users (id) ON DELETE CASCADE, 
	CONSTRAINT fk_applications_resume_id_resumes FOREIGN KEY(resume_id) REFERENCES resumes (id) ON DELETE SET NULL, 
	CONSTRAINT ck_applications_applicationstatus CHECK (status IN ('applied', 'under_review', 'shortlisted', 'interview', 'selected', 'rejected', 'withdrawn'))
);
CREATE INDEX ix_applications_opportunity ON applications (opportunity_id, status);
CREATE INDEX ix_applications_student ON applications (student_id, status);
COMMENT ON TABLE applications IS 'One application per student per listing. The database blocks duplicates.';

CREATE TABLE opportunity_departments (
	opportunity_id UUID NOT NULL, 
	department_id UUID NOT NULL, 
	CONSTRAINT pk_opportunity_departments PRIMARY KEY (opportunity_id, department_id), 
	CONSTRAINT fk_opportunity_departments_opportunity_id_opportunities FOREIGN KEY(opportunity_id) REFERENCES opportunities (id) ON DELETE CASCADE, 
	CONSTRAINT fk_opportunity_departments_department_id_departments FOREIGN KEY(department_id) REFERENCES departments (id) ON DELETE CASCADE
);
COMMENT ON TABLE opportunity_departments IS 'Departments eligible for a listing. No rows means all departments.';

CREATE TABLE opportunity_events (
	id UUID NOT NULL, 
	opportunity_id UUID NOT NULL, 
	actor_id UUID, 
	event_type VARCHAR(40) NOT NULL, 
	changes JSONB, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	CONSTRAINT pk_opportunity_events PRIMARY KEY (id), 
	CONSTRAINT fk_opportunity_events_opportunity_id_opportunities FOREIGN KEY(opportunity_id) REFERENCES opportunities (id) ON DELETE CASCADE, 
	CONSTRAINT fk_opportunity_events_actor_id_users FOREIGN KEY(actor_id) REFERENCES users (id) ON DELETE SET NULL
);
CREATE INDEX ix_opportunity_events_opportunity ON opportunity_events (opportunity_id, created_at);
COMMENT ON TABLE opportunity_events IS 'Change history for each listing (created, edited, paused, closed).';

CREATE TABLE opportunity_reports (
	id UUID NOT NULL, 
	opportunity_id UUID NOT NULL, 
	reporter_id UUID, 
	reason VARCHAR(24) NOT NULL, 
	details TEXT, 
	status VARCHAR(24) DEFAULT 'open' NOT NULL, 
	resolved_by UUID, 
	resolution_notes TEXT, 
	resolved_at TIMESTAMP WITH TIME ZONE, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	CONSTRAINT pk_opportunity_reports PRIMARY KEY (id), 
	CONSTRAINT fk_opportunity_reports_opportunity_id_opportunities FOREIGN KEY(opportunity_id) REFERENCES opportunities (id) ON DELETE CASCADE, 
	CONSTRAINT fk_opportunity_reports_reporter_id_users FOREIGN KEY(reporter_id) REFERENCES users (id) ON DELETE SET NULL, 
	CONSTRAINT ck_opportunity_reports_reportreason CHECK (reason IN ('inaccurate', 'suspicious', 'expired', 'other')), 
	CONSTRAINT ck_opportunity_reports_reportstatus CHECK (status IN ('open', 'investigating', 'resolved', 'dismissed')), 
	CONSTRAINT fk_opportunity_reports_resolved_by_users FOREIGN KEY(resolved_by) REFERENCES users (id) ON DELETE SET NULL
);
CREATE INDEX ix_opportunity_reports_status ON opportunity_reports (status);
COMMENT ON TABLE opportunity_reports IS 'Reports of suspicious or inaccurate listings.';

CREATE TABLE opportunity_reviews (
	id UUID NOT NULL, 
	opportunity_id UUID NOT NULL, 
	reviewer_id UUID, 
	decision VARCHAR(24) NOT NULL, 
	notes TEXT, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	CONSTRAINT pk_opportunity_reviews PRIMARY KEY (id), 
	CONSTRAINT fk_opportunity_reviews_opportunity_id_opportunities FOREIGN KEY(opportunity_id) REFERENCES opportunities (id) ON DELETE CASCADE, 
	CONSTRAINT fk_opportunity_reviews_reviewer_id_users FOREIGN KEY(reviewer_id) REFERENCES users (id) ON DELETE SET NULL, 
	CONSTRAINT ck_opportunity_reviews_reviewstatus CHECK (decision IN ('pending', 'approved', 'rejected', 'needs_info'))
);
CREATE INDEX ix_opportunity_reviews_opportunity ON opportunity_reviews (opportunity_id);
COMMENT ON TABLE opportunity_reviews IS 'Admin review outcomes for listings.';

CREATE TABLE opportunity_skills (
	opportunity_id UUID NOT NULL, 
	skill_id UUID NOT NULL, 
	importance VARCHAR(24) NOT NULL, 
	min_level INTEGER DEFAULT 3 NOT NULL, 
	CONSTRAINT pk_opportunity_skills PRIMARY KEY (opportunity_id, skill_id), 
	CONSTRAINT ck_opportunity_skills_level_range CHECK (min_level BETWEEN 1 AND 5), 
	CONSTRAINT fk_opportunity_skills_opportunity_id_opportunities FOREIGN KEY(opportunity_id) REFERENCES opportunities (id) ON DELETE CASCADE, 
	CONSTRAINT fk_opportunity_skills_skill_id_skills FOREIGN KEY(skill_id) REFERENCES skills (id) ON DELETE CASCADE, 
	CONSTRAINT ck_opportunity_skills_importance CHECK (importance IN ('required', 'preferred'))
);
CREATE INDEX ix_opportunity_skills_skill ON opportunity_skills (skill_id);
COMMENT ON TABLE opportunity_skills IS 'Skills a listing asks for.';

CREATE TABLE recommendations (
	id UUID NOT NULL, 
	student_id UUID NOT NULL, 
	opportunity_id UUID NOT NULL, 
	match_pct INTEGER NOT NULL, 
	matched_skills JSONB NOT NULL, 
	improving_skills JSONB NOT NULL, 
	missing_skills JSONB NOT NULL, 
	explanation TEXT NOT NULL, 
	algorithm_version VARCHAR(32) NOT NULL, 
	status VARCHAR(24) DEFAULT 'shown' NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	CONSTRAINT pk_recommendations PRIMARY KEY (id), 
	CONSTRAINT ck_recommendations_pct_range CHECK (match_pct BETWEEN 0 AND 100), 
	CONSTRAINT uq_recommendations_student_opportunity_version UNIQUE (student_id, opportunity_id, algorithm_version), 
	CONSTRAINT fk_recommendations_student_id_users FOREIGN KEY(student_id) REFERENCES users (id) ON DELETE CASCADE, 
	CONSTRAINT fk_recommendations_opportunity_id_opportunities FOREIGN KEY(opportunity_id) REFERENCES opportunities (id) ON DELETE CASCADE, 
	CONSTRAINT ck_recommendations_recommendationstatus CHECK (status IN ('shown', 'saved', 'dismissed', 'applied'))
);
CREATE INDEX ix_recommendations_student ON recommendations (student_id, match_pct);
COMMENT ON TABLE recommendations IS 'Explainable recommendations. Stores the reasons, not just a score.';
COMMENT ON COLUMN recommendations.explanation IS 'Plain-language reason shown next to the score.';

CREATE TABLE saved_opportunities (
	student_id UUID NOT NULL, 
	opportunity_id UUID NOT NULL, 
	saved_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	CONSTRAINT pk_saved_opportunities PRIMARY KEY (student_id, opportunity_id), 
	CONSTRAINT fk_saved_opportunities_student_id_users FOREIGN KEY(student_id) REFERENCES users (id) ON DELETE CASCADE, 
	CONSTRAINT fk_saved_opportunities_opportunity_id_opportunities FOREIGN KEY(opportunity_id) REFERENCES opportunities (id) ON DELETE CASCADE
);
COMMENT ON TABLE saved_opportunities IS 'Bookmarked listings.';

CREATE TABLE application_status_history (
	id UUID NOT NULL, 
	application_id UUID NOT NULL, 
	from_status VARCHAR(24), 
	to_status VARCHAR(24) NOT NULL, 
	changed_by UUID, 
	reason TEXT, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	CONSTRAINT pk_application_status_history PRIMARY KEY (id), 
	CONSTRAINT fk_application_status_history_application_id_applications FOREIGN KEY(application_id) REFERENCES applications (id) ON DELETE CASCADE, 
	CONSTRAINT ck_application_status_history_from_status CHECK (from_status IN ('applied', 'under_review', 'shortlisted', 'interview', 'selected', 'rejected', 'withdrawn')), 
	CONSTRAINT ck_application_status_history_to_status CHECK (to_status IN ('applied', 'under_review', 'shortlisted', 'interview', 'selected', 'rejected', 'withdrawn')), 
	CONSTRAINT fk_application_status_history_changed_by_users FOREIGN KEY(changed_by) REFERENCES users (id) ON DELETE SET NULL
);
CREATE INDEX ix_status_history_application ON application_status_history (application_id, created_at);
COMMENT ON TABLE application_status_history IS 'Timeline of every status change shown to the student.';

CREATE TABLE interviews (
	id UUID NOT NULL, 
	application_id UUID NOT NULL, 
	starts_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	ends_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	timezone VARCHAR(64) DEFAULT 'Asia/Kolkata' NOT NULL, 
	mode VARCHAR(24) NOT NULL, 
	meeting_url VARCHAR(500), 
	venue VARCHAR(300), 
	instructions TEXT, 
	documents_to_bring TEXT, 
	status VARCHAR(24) DEFAULT 'scheduled' NOT NULL, 
	created_by UUID, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	CONSTRAINT pk_interviews PRIMARY KEY (id), 
	CONSTRAINT ck_interviews_time_order CHECK (ends_at > starts_at), 
	CONSTRAINT fk_interviews_application_id_applications FOREIGN KEY(application_id) REFERENCES applications (id) ON DELETE CASCADE, 
	CONSTRAINT ck_interviews_interviewmode CHECK (mode IN ('online', 'on_site', 'phone')), 
	CONSTRAINT ck_interviews_interviewstatus CHECK (status IN ('scheduled', 'rescheduled', 'cancelled', 'completed')), 
	CONSTRAINT fk_interviews_created_by_users FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE SET NULL
);
CREATE INDEX ix_interviews_application ON interviews (application_id);
CREATE INDEX ix_interviews_start ON interviews (starts_at);
COMMENT ON TABLE interviews IS 'Scheduled interviews with mode, link or venue and instructions.';

CREATE TABLE placements (
	id UUID NOT NULL, 
	application_id UUID NOT NULL, 
	student_id UUID NOT NULL, 
	company_id UUID NOT NULL, 
	batch_id UUID, 
	offer_type VARCHAR(24) NOT NULL, 
	compensation NUMERIC(12, 2), 
	currency VARCHAR(3) DEFAULT 'INR' NOT NULL, 
	pay_period VARCHAR(24), 
	accepted_at TIMESTAMP WITH TIME ZONE, 
	joined_on DATE, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	CONSTRAINT pk_placements PRIMARY KEY (id), 
	CONSTRAINT uq_placements_application UNIQUE (application_id), 
	CONSTRAINT fk_placements_application_id_applications FOREIGN KEY(application_id) REFERENCES applications (id) ON DELETE CASCADE, 
	CONSTRAINT fk_placements_student_id_users FOREIGN KEY(student_id) REFERENCES users (id) ON DELETE CASCADE, 
	CONSTRAINT fk_placements_company_id_companies FOREIGN KEY(company_id) REFERENCES companies (id) ON DELETE CASCADE, 
	CONSTRAINT fk_placements_batch_id_batches FOREIGN KEY(batch_id) REFERENCES batches (id) ON DELETE SET NULL, 
	CONSTRAINT ck_placements_jobtype CHECK (offer_type IN ('internship', 'full_time')), 
	CONSTRAINT ck_placements_payperiod CHECK (pay_period IN ('monthly', 'yearly', 'one_time'))
);
CREATE INDEX ix_placements_batch ON placements (batch_id);
COMMENT ON TABLE placements IS 'Confirmed outcomes used for placement reports by batch and department.';

-- Reporting views
CREATE OR REPLACE VIEW v_application_funnel AS
SELECT o.id AS opportunity_id, o.company_id, o.title, o.status AS listing_status,
       COUNT(a.id) AS applicants,
       SUM(CASE WHEN a.status = 'under_review' THEN 1 ELSE 0 END) AS under_review,
       SUM(CASE WHEN a.status = 'shortlisted' THEN 1 ELSE 0 END) AS shortlisted,
       SUM(CASE WHEN a.status = 'interview' THEN 1 ELSE 0 END) AS interviewing,
       SUM(CASE WHEN a.status = 'selected' THEN 1 ELSE 0 END) AS selected,
       SUM(CASE WHEN a.status = 'rejected' THEN 1 ELSE 0 END) AS rejected
FROM opportunities o
LEFT JOIN applications a ON a.opportunity_id = o.id
GROUP BY o.id, o.company_id, o.title, o.status;

CREATE OR REPLACE VIEW v_applications_by_department AS
SELECT sp.college_id, d.name AS department, a.status, COUNT(*) AS applications
FROM applications a
JOIN student_profiles sp ON sp.user_id = a.student_id
LEFT JOIN departments d ON d.id = sp.department_id
GROUP BY sp.college_id, d.name, a.status;

CREATE OR REPLACE VIEW v_placements_by_batch AS
SELECT b.college_id, b.label AS batch, COUNT(p.id) AS placements,
       (SELECT COUNT(*) FROM student_profiles s WHERE s.batch_id = b.id) AS students_in_batch
FROM batches b
LEFT JOIN placements p ON p.batch_id = b.id
GROUP BY b.id, b.college_id, b.label;
